DO $$ BEGIN IF current_database() !~ '^carelink_shadow' THEN RAISE EXCEPTION 'DISPOSABLE_DB_REQUIRED'; END IF; END $$;
CREATE OR REPLACE FUNCTION pg_temp.assert_calendar(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'calendar assertion: %',label; END IF; END $$;
SELECT pg_temp.assert_calendar(NOT has_table_privilege('service_role','public.calendar_sync_operations','DELETE') AND NOT has_table_privilege('authenticated','public.calendar_sync_operations','SELECT') AND NOT has_table_privilege('anon','public.calendar_sync_operations','INSERT'),'private receipts');
SELECT pg_temp.assert_calendar(NOT has_table_privilege('authenticated','public.booking_calendar_events','INSERT') AND NOT has_table_privilege('authenticated','public.booking_calendar_events','UPDATE') AND NOT has_table_privilege('authenticated','public.booking_calendar_events','DELETE'),'no browser mutation bypass');
SELECT pg_temp.assert_calendar(NOT has_function_privilege('authenticated','public.prepare_calendar_operation(uuid,uuid,uuid,text,jsonb,text,uuid,timestamptz)','EXECUTE') AND has_function_privilege('service_role','public.prepare_calendar_operation(uuid,uuid,uuid,text,jsonb,text,uuid,timestamptz)','EXECUTE'),'service-only RPC');
SELECT pg_temp.assert_calendar(NOT EXISTS(SELECT 1 FROM pg_proc WHERE proname IN ('inspect_calendar_operation','prepare_calendar_operation','start_calendar_operation','finish_calendar_operation') AND (prosecdef OR proconfig IS DISTINCT FROM ARRAY['search_path=""'])),'fixed invoker functions');
